head.script:
//
/* Identical polyfill to https://cdn.jsdelivr.net/gh/OpiumBest/svg/index.svg */
(function () {
  var XHTML_NS = "http://www.w3.org/1999/xhtml";
  var root = document.querySelector("foreignObject").firstElementChild;
  var originalCreateElement = document.createElement.bind(document);
  var originalCreateElementNS = document.createElementNS.bind(document);
  Object.defineProperty(document, "head", {
    get: function () { return root.querySelector("head"); },
    configurable: true
  });
  Object.defineProperty(document, "body", {
    get: function () { return root.querySelector("body"); },
    configurable: true
  });
  Object.defineProperty(document, "documentElement", {
    get: function () { return root; },
    configurable: true
  });
  document.createElement = function (tagName, options) {
    if (typeof tagName === "string") {
      return originalCreateElementNS(XHTML_NS, tagName, options);
    }
    return originalCreateElement(tagName, options);
  };
  document.createElementNS = function (namespaceURI, qualifiedName, options) {
    if (namespaceURI == null || namespaceURI === XHTML_NS) {
      return originalCreateElementNS(XHTML_NS, qualifiedName, options);
    }
    return originalCreateElementNS(namespaceURI, qualifiedName, options);
  };
})();
//

//
(async function () {
  /*
    Opium pattern: stay on this SVG URL so location is
      https://cdn.jsdelivr.net/gh/USER/REPO/index.svg
    and sw.js resolves to
      https://cdn.jsdelivr.net/gh/USER/REPO/sw.js
    Do NOT blob-iframe (that breaks SW paths).
  */
  var boot = document.getElementById("boot");
  function status(t) { if (boot) boot.textContent = t; }

  var pageUrl = new URL("index.html", location.href).href;
  status("Loading " + pageUrl + " …");

  try {
    var res = await fetch(pageUrl, { cache: "no-store", mode: "cors" });
    if (!res.ok) throw new Error("HTTP " + res.status + " fetching index.html");
    var html = await res.text();
    if (!html || html.length < 100) throw new Error("index.html empty");

    // Parse as HTML document
    var parsed = new DOMParser().parseFromString(html, "text/html");

    // Base for relative asset URLs inside the injected page
    var baseHref = new URL(".", location.href).href;
    var baseTag = document.createElement("base");
    baseTag.setAttribute("href", baseHref);
    document.head.insertBefore(baseTag, document.head.firstChild);

    // Copy <link> and <style> from parsed head
    var headNodes = parsed.head ? parsed.head.childNodes : [];
    for (var i = 0; i < headNodes.length; i++) {
      var node = headNodes[i];
      if (!node.tagName) continue;
      var tag = node.tagName.toLowerCase();
      if (tag === "script") continue; // scripts handled below
      if (tag === "title") {
        document.title = node.textContent || document.title;
        continue;
      }
      if (tag === "meta" || tag === "link" || tag === "style") {
        document.head.appendChild(document.importNode(node, true));
      }
    }

    // Replace body content
    var newBody = parsed.body;
    if (newBody) {
      document.body.innerHTML = "";
      while (newBody.firstChild) {
        document.body.appendChild(document.importNode(newBody.firstChild, true));
      }
    }

    // Re-execute scripts in order (external then inline), like a normal page load
    var scripts = parsed.querySelectorAll("script");
    for (var s = 0; s < scripts.length; s++) {
      await new Promise(function (resolve) {
        var orig = scripts[s];
        var el = document.createElement("script");
        if (orig.src) {
          el.src = orig.src;
          el.async = false;
          el.onload = function () { resolve(); };
          el.onerror = function () { resolve(); };
          document.head.appendChild(el);
        } else {
          el.textContent = orig.textContent || "";
          document.head.appendChild(el);
          resolve();
        }
      });
    }

    status("");
  } catch (err) {
    var m = (err && err.message) ? err.message : String(err);
    status("Failed: " + m + " — ensure index.html + sw.js sit next to this SVG in the repo (same as OpiumBest/svg).");
  }
})();
//
